    /// <summary>
    /// Category group, Use Item Attributes, Product Pricing Attribute fields must be visible only for Rebate Item Groups
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get form data source args</param>
    [
        FormDataSourceEventHandler(formDataSourceStr(TAMRebateGroup, TAMRebateGroup), FormDataSourceEventType::Activated),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void TAMRebateGroup_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        TAMRebateGroup rebateGroup = sender.cursor();
        
        boolean isVisible;

        if(rebateGroup.ModuleInventCustVend == ModuleInventCustVend::Invent)
        {
            isVisible = true;
        }

        sender.object(fieldNum(TAMRebateGroup, METCategoryGroup)).visible(isVisible);
        sender.object(fieldNum(TAMRebateGroup, METUseItemAttributes)).visible(isVisible);
        sender.object(fieldNum(TAMRebateGroup, METGUPProductPricingAttributeGroup)).visible(isVisible);
    }

/// <summary>
/// Enable Disable Items,GetItems control in Item Group form based on METUseItemAttributes status
/// </summary>
/// <param name="sender">METUseItemAttributes control</param>
/// <param name="e">On modified event args</param>
[FormControlEventHandler(formControlStr(TAMRebateGroup, TAMRebateGroup_METUseItemAttributes), FormControlEventType::Modified),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void TAMRebateGroup_METUseItemAttributes_OnModified(FormControl sender, FormControlEventArgs e)
{
    METTAMRebateGroupFormEventHandler::METUpdateDesign(sender.formRun());
}

/// <summary>
/// initialize the MET fields for new record for Item Group
/// </summary>
/// <param name="sender">TAMRebateGroup data source</param>
/// <param name="e">init event</param>
[FormDataSourceEventHandler(formDataSourceStr(TAMRebateGroup, TAMRebateGroup), FormDataSourceEventType::InitValue),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void TAMRebateGroup_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
{
    TAMRebateGroup rebateGroup = sender.cursor();
    
    if(rebateGroup.ModuleInventCustVend == ModuleInventCustVend::Invent)
    {
        rebateGroup.METUseItemAttributes = NoYes::Yes;
    }
}

/// <summary>
/// update design on the record selection change
/// </summary>
/// <param name="sender">TAMRebateGroup data source</param>
/// <param name="e">event</param>
[FormDataSourceEventHandler(formDataSourceStr(TAMRebateGroup, TAMRebateGroup), FormDataSourceEventType::SelectionChanged),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void TAMRebateGroup_OnSelectionChanged(FormDataSource sender, FormDataSourceEventArgs e)
{
    METTAMRebateGroupFormEventHandler::METUpdateDesign(sender.formRun());
}

    /// <summary>
    /// Enable/disable control elements based on different conditions
    /// </summary>
    /// <param name = "_formRun"><c>FormRun</c> object</param>
    public static void METUpdateDesign(FormRun _formRun)
    {
        TAMRebateGroup rebateGroup = _formRun.dataSource(tableStr(TAMRebateGroup)).cursor();
        boolean isEnabled = true;
            
        if(rebateGroup.ModuleInventCustVend == ModuleInventCustVend::Invent && rebateGroup.METUseItemAttributes)
        {
            isEnabled = false;
        }

        _formRun.design().controlName(formControlStr(TAMRebateGroup,TAMRebateGroupLink )).enabled(isEnabled);
        _formRun.design().controlName(formControlStr(TAMRebateGroup,TAMRebateGroupAddItemsController )).enabled(isEnabled);
    }

    /// <summary>
    /// Enable the Change Dialog only for Item Group and not for Customer and Vendor Groups
    /// </summary>
    /// <param name="sender">FormRun sender</param>
    /// <param name="e">event , not used </param>
    [FormEventHandler(formStr(TAMRebateGroup), FormEventType::Initialized),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void TAMRebateGroup_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        ModuleInventCustVend moduleName = sender.args().parmEnum();

        sender.design(0).controlName(menuItemDisplayStr(METTAMRebateItemGroupAttributeChangeDialog)).visible(moduleName == ModuleInventCustVend::Invent);
    }

/// <summary>
/// Handler for post run
/// </summary>
/// <param name="sender">formrun sender</param>
/// <param name="e">event, not used</param>
[FormEventHandler(formStr(TAMRebateGroup), FormEventType::PostRun),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void TAMRebateGroup_OnPostRun(xFormRun sender, FormEventArgs e)
{
    FormStringControl   control = sender.design().controlName(formControlStr(TAMRebateGroup, TAMRebateGroup_METGUPProductPricingAttributeGroup));
    control.registerOverrideMethod(methodStr(FormStringControl, jumpRef), methodStr(METTAMRebateGroupForm_Extension, METJumpRef_PricingAttributeGroup), sender);
}
